// The interface icons of docs/design/system/project/icons/icons.json, as Dart: the web reads that
// file, the phone this copy, and test/ui/lk_icon_test.dart fails when the two differ. Change the JSON
// first, then this file the same way. home and chart are Plump Free and the settings icons Plump Solid Free,
// both by Streamline (streamlinehq.com), CC BY 4.0 (credited in About's licences); the rest are
// Wambito's own.

/// An interface icon; [id] is its name in icons.json.
enum LkIconName {
  search('search'),
  user('user'),
  home('home'),
  chart('chart'),
  plus('plus'),
  close('close'),
  chevronLeft('chevron-left'),
  chevronRight('chevron-right'),
  mic('mic'),
  check('check'),
  cloudOff('cloud-off'),
  shield('shield'),
  sliders('sliders'),
  bell('bell'),
  folder('folder'),
  info('info'),
  fingerprint('fingerprint'),
  phone('phone'),
  laptop('laptop'),
  key('key'),
  trash('trash'),
  wand('wand'),
  calendar('calendar'),
  widget('widget'),
  eyeOff('eye-off'),
  globe('globe'),
  moon('moon'),
  volume('volume'),
  clock('clock'),
  coin('coin'),
  upload('upload'),
  download('download'),
  server('server'),
  map('map'),
  chat('chat');

  const LkIconName(this.id);
  final String id;

  static LkIconName fromId(String id) =>
      values.firstWhere((name) => name.id == id);
}

/// `filled` everywhere but an inactive tab, which is `outline`.
enum LkIconVariant { filled, outline }

/// One shape on the 48 grid: [d] is SVG path data, filled when [fill] (even-odd when [evenOdd]), else
/// stroked [stroke] wide with round caps and joins.
class LkIconShape {
  const LkIconShape(
    this.d, {
    this.fill = false,
    this.evenOdd = false,
    this.stroke = 0,
  });

  final String d;
  final bool fill;
  final bool evenOdd;
  final double stroke;

  @override
  bool operator ==(Object other) =>
      other is LkIconShape &&
      other.d == d &&
      other.fill == fill &&
      other.evenOdd == evenOdd &&
      other.stroke == stroke;

  @override
  int get hashCode => Object.hash(d, fill, evenOdd, stroke);
}

