/// The shapes of [name] in [variant], the filled ones when it has no outline.
List<LkIconShape> shapesOf(LkIconName name, LkIconVariant variant) {
  final icon = lkIconShapes[name]!;
  return icon[variant] ?? icon[LkIconVariant.filled]!;
}
